<template>
	<view class="container">
		<u-loading-page :loading="true" v-if="load" fontSize="28rpx" />
		<block v-else>
			<view class="top-border"></view>
			<view class="item-top">
				<view class="item">
					<text>会员头像</text>
					<text>会员账号</text>
					<text>排名</text>
					<text>{{getText}}</text>
				</view>
			</view>
			<view class="inner" v-if="lists.length>0">
				<view class="items">
					<view class="item" v-for="(item,index) in lists" :key="index">
						<view class="item-img">
							<image :src="item.head_pic" mode="aspectFit" class="left-img" />
						</view>
						<text>{{item.mobile}}</text>
						<text>{{index + 1}}</text>
						<text>{{item.yeji}}</text>
					</view>
				</view>
				<u-loadmore class="load-more" :status="hasMore?'loading':'nomore'" :nomoreText="noMore" />
			</view>
			<view class="empty-view" v-else>
			<view class="empty-container">
				<u-empty text="暂无数据" :icon="emptyIcon" />
			</view>
			</view>
		</block>
	</view>
</template>

<script>
	var _this;
	export default {
		data() {
			return {
				type:1,
			}
		},
		onLoad(e) {
			_this = this;
			if (e.type) {
				_this.type = Number(e.type)
			}
			this.get_yeji_list()
		},
		onReady() {
			var title = ''
			switch (this.type){
				case 1:
					title = '总销售额'
					break;
				case 2:
					title = '月销售额'
					break;
				case 3:
					title = '团队销售额'
					break;
				default:
				title = '团队月销售额'
					break;
			}
			if (title) {
				uni.setNavigationBarTitle({
					title:title
				})
			}
		},
		methods: {
			async get_yeji_list() {
				const params = {
					type: _this.type,
				}
				const data = await _this.$post('port/yeji_list', params)
				if (data.code == 200) {
					_this.lists = data.result.list
					_this.hasMore = false
				} else {
					_this.hasMore = false
				}
				if (_this.load) {
					_this.load = false
				}
			}
		},
		computed:{
			getText:{
				cache:false,
				get() {
					let title = ''
					switch (this.type){
						case 1:
						title = '总销售额'
							break;
						case 2:
						title = '月销售额'
							break;
						case 3:
						title = '团队销售额'
							break;
						default:
						title = '团队月销售额'
							break;
					}
					return title
				}
			}
		}
	}
</script>

